mapper.select:
SELECT channel_id channelId, COUNT(*) childCount FROM t_channel_script WHERE channel_id IN
#{id}
GROUP BY channel_id

mapper.update:
UPDATE t_channel_script SET script_name=#{scriptName}, execution_stage=#{executionStage.code},
parameter_definition=#{parameterDefinition}, source_code=#{sourceCode}, description=#{description},
version=version+1, updated_by=#{updatedBy}, update_time=#{updateTime}
WHERE channel_script_id=#{row.channelScriptId} AND version=#{row.version}
